        .nav a:hover {
            color: #2d2d2d;
        }

        .nav a.active {
            color: #2d2d2d;
            font-weight: 600;
        }

        .nav a.active::after {
            content: '';
            position: absolute;
            bottom: -4px;
            left: 0;
            right: 0;
            height: 2px;
            background: #2d2d2d;
        }

        .header-icons {
            display: flex;
            gap: 20px;
            align-items: center;
        }

        .header-icons a {
            font-size: 14px;
            color: #555;
            transition: color 0.3s;
